+	if tip == "" {
+		return "", steps, nil
+	}
+	if out, err := run("push", "origin", "HEAD:refs/heads/"+branch); err != nil {
+		return "", nil, fmt.Errorf("push %s: %w\n%s", branch, err, c.redact(string(out)))
+	}
