+	}
+	if f.target != wantSHA {
+		t.Fatalf("target = %q, want fast-forward to %q", f.target, wantSHA)
+	}
+	if b.State != pg.BatchStateDone || len(b.LandedIds) != 3 || b.Flaky {
+		t.Fatalf("unexpected batch after pass: %+v", b)
