+	// FormAndBuild is a no-op on an empty queue.
+	if b2, err := e.FormAndBuild(ctx, "main"); err != nil || b2 != nil {
+		t.Fatalf("FormAndBuild on empty queue: b=%v err=%v", b2, err)
